WHERE slug = 'clearscope' AND lang = 'ua';

UPDATE tools SET
  best_for         = $d42u$AI-пошук та дослідження з верифікованими джерелами$d42u$,
  description      = $d42u$Perplexity — AI-пошукова система, що відповідає на запитання з актуальною інформацією з інтернету, завжди вказуючи джерела для верифікації.$d42u$,
  description_long = $dl42u$Perplexity поєднує можливості великих мовних моделей з пошуком у мережі в реальному часі, пропонуючи точні відповіді з посиланнями на оригінальні джерела. На відміну від ChatGPT, завжди надає посилання на статті, з яких походить інформація. У режимі Pro отримує доступ до більш просунутих моделей і може аналізувати файли. Ідеально для академічних досліджень, журналістики та ринкового аналізу.$dl42u$,
  pros = ARRAY['Джерела завжди вказуються', 'Інформація в реальному часі', 'Режим Pro з просунутими моделями', 'Безкоштовна версія дуже корисна'],
  cons = ARRAY['Менш творчий ніж ChatGPT для написання', 'Безкоштовний тариф з обмеженням Pro-пошуків', 'Може змішувати джерела різної якості']
WHERE slug = 'perplexity' AND lang = 'ua';

UPDATE tools SET
  best_for         = $d43u$AI-асистент, інтегрований в екосистему Microsoft 365$d43u$,
