  pros = ARRAY['Нативно інтегрований у Microsoft 365', 'Повний контекст документів і листів', 'Резюме зустрічей у Teams', 'Генерація презентацій у PowerPoint'],
  cons = ARRAY['Потребує ліцензії Microsoft 365 Copilot за $30/користувача/місяць', 'Змінна якість залежно від застосунку', 'Менш потужний поза екосистемою Microsoft']
WHERE slug = 'microsoft-copilot' AND lang = 'ua';

UPDATE tools SET
  best_for         = $d44u$Кастомна генерація зображень з моделлю з відкритим кодом$d44u$,
  description      = $d44u$Stable Diffusion — найбільш використовувана у світі open-source модель генерації зображень, що може запускатися локально, налаштовуватися з fine-tuning та використовуватися без обмежень контенту.$d44u$,
  description_long = $dl44u$Stable Diffusion та його екосистема (AUTOMATIC1111, ComfyUI, моделі Civitai) представляють найгнучкішу опцію на ринку. При локальному запуску немає обмежень використання, цензури або вартості за зображення. Спільнота створила тисячі спеціалізованих моделей безкоштовно. З ControlNet можна контролювати композицію з міліметровою точністю. Крива навчання висока, але творчий контроль непереверершений.$dl44u$,
  pros = ARRAY['100% безкоштовно та з відкритим кодом', 'Без обмежень використання та цензури', 'Тисячі спільнотних моделей', 'Повний контроль з ControlNet'],
  cons = ARRAY['Потребує потужного GPU для локального використання', 'Дуже висока крива навчання', 'Непослідовні результати без правильного налаштування']
WHERE slug = 'stable-diffusion' AND lang = 'ua';

UPDATE tools SET
